def parse_demo(t, kind, num):
    m=re.search(rf'Demo pair {num} {kind} \(16x16\):\n((?:[0-9 ]+\n){{16}})',t)
    return [[int(x) for x in line.split()] for line in m.group(1).splitlines()]
def cc_non7(g):
    R,C=len(g),len(g[0]);seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if g[r][c]==7 or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c));cells=[]
        for rr,cc in q:
          cells.append((rr,cc))
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=rr+dr,cc+dc
            if 0<=nr<R and 0<=nc<C and g[nr][nc]!=7 and (nr,nc) not in seen:
              seen.add((nr,nc));q.append((nr,nc))
        comps.append((cells,{g[a][b] for a,b in cells}))
    return comps
